                required: [webhook, deliveries]
                properties:
                  webhook:
                    $ref: '#/components/schemas/Webhook'
                  deliveries:
                    $ref: '#/components/schemas/DeliveryCounts'
        '401':
          $ref: '#/components/responses/Unauthorized'
        '403':
          $ref: '#/components/responses/Forbidden'
        '404':
          $ref: '#/components/responses/NotFound'
    patch:
      tags: [webhooks]
      operationId: updateWebhook
      summary: Changes a webhook.
      security:
        - cookieAuth: []
          csrfHeader: []
        - bearerAuth: []
      parameters:
        - $ref: '#/components/parameters/Id'
      requestBody:
        required: true
        content:
          application/json:
            schema:
              type: object
              properties:
                url:
                  type: string
                  format: uri
                events:
                  type: array
                  items:
                    $ref: '#/components/schemas/WebhookEvent'
                description:
                  type: string
                enabled:
                  type: boolean
      responses:
        '200':
          description: Changed.
          content:
            application/json:
              schema:
                type: object
                required: [webhook]
                properties:
                  webhook:
                    $ref: '#/components/schemas/Webhook'
        '400':
          $ref: '#/components/responses/Invalid'
        '401':
          $ref: '#/components/responses/Unauthorized'
        '403':
          $ref: '#/components/responses/Forbidden'
        '404':
          $ref: '#/components/responses/NotFound'
    delete:
      tags: [webhooks]
      operationId: deleteWebhook
      summary: Deletes a webhook and its deliveries.
      security:
        - cookieAuth: []
          csrfHeader: []
        - bearerAuth: []
      parameters:
        - $ref: '#/components/parameters/Id'
      responses:
        '200':
          $ref: '#/components/responses/Success'
        '401':
          $ref: '#/components/responses/Unauthorized'
        '403':
          $ref: '#/components/responses/Forbidden'
        '404':
          $ref: '#/components/responses/NotFound'
  /webapi/webhooks/{id}/secret:
    post:
      tags: [webhooks]
      operationId: rotateWebhookSecret
      summary: Replaces the signing secret.
      description: The new secret is in the answer only.
      security:
        - cookieAuth: []
          csrfHeader: []
        - bearerAuth: []
      parameters:
        - $ref: '#/components/parameters/Id'
      responses:
        '200':
          description: The new secret.
          content:
            application/json:
              schema:
                type: object
                required: [secret]
                properties:
                  secret:
                    type: string
        '401':
          $ref: '#/components/responses/Unauthorized'
        '403':
          $ref: '#/components/responses/Forbidden'
        '404':
          $ref: '#/components/responses/NotFound'
  /webapi/webhooks/{id}/deliveries:
    get:
      tags: [webhooks]
      operationId: listDeliveries
      summary: The deliveries of a webhook, newest first.
      security:
        - cookieAuth: []
        - bearerAuth: []
      parameters:
        - $ref: '#/components/parameters/Id'
        - $ref: '#/components/parameters/Page'
        - $ref: '#/components/parameters/Size'
      responses:
        '200':
          description: A page of deliveries.
          content:
            application/json:
              schema:
                $ref: '#/components/schemas/DeliveryPage'
        '401':
          $ref: '#/components/responses/Unauthorized'
        '403':
          $ref: '#/components/responses/Forbidden'
        '404':
          $ref: '#/components/responses/NotFound'
  /webapi/webhooks/{id}/deliveries/{delivery}/redeliver:
    post:
      tags: [webhooks]
      operationId: redeliver
      summary: Queues a delivery again, with the same payload and event id.
      security:
        - cookieAuth: []
          csrfHeader: []
        - bearerAuth: []
      parameters:
        - $ref: '#/components/parameters/Id'
        - name: delivery
          in: path
          required: true
          schema:
            type: string
      responses:
        '200':
          $ref: '#/components/responses/Success'
        '401':
          $ref: '#/components/responses/Unauthorized'
        '403':
          $ref: '#/components/responses/Forbidden'
        '404':
          $ref: '#/components/responses/NotFound'
  /api/packages/{name}/versions/{version}/retract:
    post:
      tags: [management]
      operationId: retractVersion
      summary: Retracts a version.
      description: Administrators and uploaders, within `publish.retractionWindow` for uploaders.
      security:
        - cookieAuth: []
          csrfHeader: []
        - bearerAuth: []
      parameters:
        - $ref: '#/components/parameters/Name'
        - $ref: '#/components/parameters/Version'
      responses:
        '200':
          $ref: '#/components/responses/Success'
        '401':
          $ref: '#/components/responses/Unauthorized'
        '403':
          $ref: '#/components/responses/Forbidden'
        '404':
          $ref: '#/components/responses/NotFound'
  /api/packages/{name}/versions/{version}/unretract:
    post:
      tags: [management]
      operationId: unretractVersion
      summary: Restores a retracted version.
      security:
        - cookieAuth: []
          csrfHeader: []
        - bearerAuth: []
      parameters:
        - $ref: '#/components/parameters/Name'
        - $ref: '#/components/parameters/Version'
      responses:
        '200':
          $ref: '#/components/responses/Success'
        '401':
          $ref: '#/components/responses/Unauthorized'
        '403':
          $ref: '#/components/responses/Forbidden'
        '404':
          $ref: '#/components/responses/NotFound'
  /api/packages/{name}/versions/{version}:
    delete:
      tags: [management]
      operationId: deleteVersion
      summary: Deletes a version and its archive.
      description: Administrators. The last version cannot be deleted, delete the package instead (409).
      security:
        - cookieAuth: []
          csrfHeader: []
        - bearerAuth: []
      parameters:
        - $ref: '#/components/parameters/Name'
        - $ref: '#/components/parameters/Version'
      responses:
        '200':
          $ref: '#/components/responses/Success'
        '401':
          $ref: '#/components/responses/Unauthorized'
        '403':
          $ref: '#/components/responses/Forbidden'
        '404':
          $ref: '#/components/responses/NotFound'
        '409':
          $ref: '#/components/responses/Conflict'
  /api/packages/{name}:
    delete:
      tags: [management]
      operationId: deletePackage
      summary: Deletes a package, its versions, archives and statistics.
      description: Administrators.
      security:
        - cookieAuth: []
          csrfHeader: []
        - bearerAuth: []
      parameters:
        - $ref: '#/components/parameters/Name'
      responses:
        '200':
          $ref: '#/components/responses/Success'
        '401':
          $ref: '#/components/responses/Unauthorized'
        '403':
          $ref: '#/components/responses/Forbidden'
        '404':
          $ref: '#/components/responses/NotFound'
  /api/packages/{name}/discontinue:
    put:
      tags: [management]
      operationId: setDiscontinued
      summary: Discontinues a package, or continues it.
      description: Administrators and uploaders.
      security:
        - cookieAuth: []
          csrfHeader: []
        - bearerAuth: []
      parameters:
        - $ref: '#/components/parameters/Name'
      requestBody:
        required: true
        content:
          application/json:
            schema:
              type: object
              required: [isDiscontinued]
              properties:
                isDiscontinued:
                  type: boolean
                replacedBy:
                  type: [string, 'null']
                  description: A package on this server.
      responses:
        '200':
          $ref: '#/components/responses/Success'
        '400':
          $ref: '#/components/responses/Invalid'
        '401':
          $ref: '#/components/responses/Unauthorized'
        '403':
          $ref: '#/components/responses/Forbidden'
        '404':
          $ref: '#/components/responses/NotFound'
  /api/packages/{name}/owner:
    put:
      tags: [management]
      operationId: transferOwnership
      summary: Makes one user the only uploader.
      description: Administrators. The user must exist and be allowed to publish.
      security:
        - cookieAuth: []
          csrfHeader: []
        - bearerAuth: []
      parameters:
        - $ref: '#/components/parameters/Name'
      requestBody:
        required: true
        content:
          application/json:
            schema:
              type: object
              required: [email]
              properties:
                email:
                  type: string
                  format: email
      responses:
        '200':
          $ref: '#/components/responses/Success'
        '400':
          $ref: '#/components/responses/Invalid'
        '401':
          $ref: '#/components/responses/Unauthorized'
        '403':
          $ref: '#/components/responses/Forbidden'
        '404':
          $ref: '#/components/responses/NotFound'
  /api/packages/{name}/uploaders:
    post:
      tags: [management]
      operationId: addUploader
      summary: Adds an uploader.
      description: Administrators and uploaders. The body is JSON or, as `dart pub` sends it, a form.
      security:
        - cookieAuth: []
          csrfHeader: []
        - bearerAuth: []
      parameters:
        - $ref: '#/components/parameters/Name'
      requestBody:
        required: true
        content:
          application/json:
            schema:
              $ref: '#/components/schemas/EmailInput'
          application/x-www-form-urlencoded:
            schema:
              $ref: '#/components/schemas/EmailInput'
      responses:
        '200':
          $ref: '#/components/responses/Success'
        '400':
          $ref: '#/components/responses/Invalid'
        '401':
          $ref: '#/components/responses/Unauthorized'
        '403':
          $ref: '#/components/responses/Forbidden'
        '404':
          $ref: '#/components/responses/NotFound'
        '409':
          $ref: '#/components/responses/Conflict'
  /api/packages/{name}/uploaders/{email}:
    delete:
      tags: [management]
      operationId: removeUploader
      summary: Removes an uploader. The last one cannot be removed (409).
      security:
        - cookieAuth: []
          csrfHeader: []
        - bearerAuth: []
      parameters:
        - $ref: '#/components/parameters/Name'
        - name: email
          in: path
          required: true
          description: Percent-encoded.
          schema:
            type: string
      responses:
        '200':
          $ref: '#/components/responses/Success'
        '401':
          $ref: '#/components/responses/Unauthorized'
        '403':
          $ref: '#/components/responses/Forbidden'
        '404':
          $ref: '#/components/responses/NotFound'
        '409':
          $ref: '#/components/responses/Conflict'
components:
  securitySchemes:
    cookieAuth:
      type: apiKey
      in: cookie
      name: unpub_session
      description: >-
        The session cookie set by `POST /webapi/login`. A request that is not
        GET, HEAD or OPTIONS must also send `X-CSRF-Token` (see
        `csrfHeader`), or is refused with 403 `csrf_failed`.
    csrfHeader:
      type: apiKey
      in: header
      name: X-CSRF-Token
      description: The `csrfToken` of the session, from `POST /webapi/login` or `GET /webapi/me`.
    bearerAuth:
      type: http
      scheme: bearer
      description: A personal API token. Its scopes narrow what the role of its user allows.
  parameters:
    Page:
      name: page
      in: query
      description: >-
        One-based, at most 100000. Read leniently: a value that is not a
        positive integer is 1, a larger one is 100000, which is past the end of
        any list and so answers an empty page with `page: 100000`.
      schema:
        type: integer
        minimum: 1
        maximum: 100000
        default: 1
    Size:
      name: size
      in: query
      description: >-
        Read leniently: a value that is not a positive integer is the default,
        a larger one is 100.
      schema:
        type: integer
        minimum: 1
        maximum: 100
        default: 20
    Name:
      name: name
      in: path
      required: true
      description: A package name.
      schema:
        type: string
        pattern: '^[a-zA-Z_][a-zA-Z0-9_]*$'
    Version:
      name: version
      in: path
      required: true
      description: A version, percent-encoded, such as `1.0.0%2B1` for `1.0.0+1`.
      schema:
        type: string
    Id:
      name: id
      in: path
      required: true
      schema:
        type: string
  responses:
    Success:
      description: Done.
      content:
        application/json:
          schema:
            $ref: '#/components/schemas/Success'
    Invalid:
      description: The request is invalid, code `invalid_request`.
      content:
        application/json:
          schema:
            $ref: '#/components/schemas/Error'
    Unauthorized:
      description: Credentials are missing or not accepted, code `unauthorized`.
      headers:
        WWW-Authenticate:
          schema:
            type: string
      content:
        application/json:
          schema:
            $ref: '#/components/schemas/Error'
    Forbidden:
      description: >-
        Not allowed: `forbidden`, `insufficient_scope` for a token without the
        scope, `session_required` for a change only a password login may make,
        `csrf_failed` for a session without a valid `X-CSRF-Token`.
      content:
        application/json:
          schema:
            $ref: '#/components/schemas/Error'
    NotFound:
      description: Not found, code `not_found`.
      content:
        application/json:
          schema:
            $ref: '#/components/schemas/Error'
    Conflict:
      description: >-
        In conflict with the current state, code `conflict`, `last_admin` or
        `admin_change_in_progress`.
      content:
        application/json:
          schema:
            $ref: '#/components/schemas/Error'
    RateLimited:
      description: >-
        Too many failed attempts, code `rate_limited`. `Retry-After` gives the
        seconds to wait.
      headers:
        Retry-After:
          schema:
            type: integer
      content:
        application/json:
          schema:
            $ref: '#/components/schemas/Error'
  schemas:
    Error:
      type: object
      required: [error]
      properties:
        error:
          type: object
          required: [code, message]
          properties:
            code:
              type: string
              examples: [not_found]
            message:
              type: string
            requestId:
              type: string
              description: >-
                The `X-Request-Id` of the answer. Sent with 5xx statuses
                only.
              examples: [3f9c2a7b1e0d4c6a8b5f2e1d0c9b8a7f]
    Success:
      type: object
      required: [success]
      properties:
        success:
          type: object
          required: [message]
          properties:
            message:
              type: string
    Done:
      type: object
      required: [success]
      properties:
        success:
          type: boolean
          const: true
    PageInfo:
      type: object
      required: [page, size, total]
      properties:
        page:
          type: integer
          minimum: 1
        size:
          type: integer
          minimum: 1
        total:
          type: integer
          minimum: 0
          description: How many items match, on every page.
    DateTime:
      type: string
      format: date-time
      description: ISO 8601 in UTC.
    Role:
      type: string
      enum: [admin, publisher, reader]
    Scope:
      type: string
      enum: [read, publish]
    Config:
      type: object
      required: [version, publicUrl, readAccess, accounts, upstream, features, ui]
      examples:
        - version: 3.0.0-dev.6
          publicUrl: https://pub.example.com
          readAccess: authenticated
          accounts: true
          upstream:
            url: https://pub.dev
            mode: proxy
          features:
            metrics: true
            webhooks: true
            spa: true
            classic: true
          ui:
            mode: spa
            basePath: ''
            classicPath: /classic
      properties:
        version:
          type: string
          description: The version of the server.
          examples: [3.0.0-dev.6]
        publicUrl:
          type: [string, 'null']
          description: '`server.publicUrl`, null when URLs derive from the request.'
        readAccess:
          type: string
          enum: [public, authenticated]
        accounts:
          type: boolean
          description: Whether the server has user accounts, so logging in is possible.
        upstream:
          type: object
          required: [url, mode]
          properties:
            url:
              type: string
              format: uri
            mode:
              type: string
              enum: [redirect, proxy]
        features:
          type: object
          required: [metrics, webhooks, spa, classic]
          properties:
            metrics:
              type: boolean
              description: Whether `/metrics` is served.
            webhooks:
              type: boolean
              description: Whether webhooks can be managed.
            spa:
              type: boolean
              description: Whether this client is served.
            classic:
              type: boolean
              description: Whether the server-rendered pages are served. Always true.
        ui:
          type: object
          required: [mode, basePath, classicPath]
          properties:
            mode:
              type: string
              enum: [spa, ssr]
            basePath:
              type: string
              description: Where the client is, `""` for `/`, else such as `/app`.
            classicPath:
              type: string
              description: Where the server-rendered pages are, `""` for `/`, else `/classic`.
    PackageSummary:
      type: object
      description: >-
        A package of the list. Only packages published here are listed, never
        ones only proxied from the upstream.
      required: [name, latest, description, updatedAt, downloads, isDiscontinued, replacedBy, isFlutter, private, versionCount, uploaders]
      examples:
        - name: alpha_client
          latest: 1.4.0
          description: A client for the Alpha service.
          updatedAt: '2026-11-02T09:14:00.000Z'
          downloads: 1287
          isDiscontinued: false
          replacedBy: null
          isFlutter: false
          private: true
          versionCount: 12
          uploaders: [dev@example.com, lead@example.com]
      properties:
        name:
          type: string
        latest:
          type: string
          description: The latest version, see `Package.latest`.
        description:
          type: string
        updatedAt:
          $ref: '#/components/schemas/DateTime'
        downloads:
          type: integer
        isDiscontinued:
          type: boolean
        replacedBy:
          type: [string, 'null']
        isFlutter:
          type: boolean
          description: Any version has a `flutter` section, an `environment.flutter` constraint or depends on `flutter`.
        private:
          type: boolean
          description: >-
            Published here, rather than proxied from the upstream. Always true,
            since proxied packages are not listed.
        versionCount:
          type: integer
          minimum: 1
          description: How many versions the package has, retracted ones included.
        uploaders:
          type: array
          description: The emails that may publish and manage the package, in their stored order.
          items:
            type: string
    PackagePage:
      allOf:
        - $ref: '#/components/schemas/PageInfo'
        - type: object
          required: [items]
          properties:
            items:
              type: array
              items:
                $ref: '#/components/schemas/PackageSummary'
    Dependency:
      type: object
      required: [name, constraint, hosted, local]
      properties:
        name:
          type: string
        constraint:
          type: [string, 'null']
          description: The version constraint, null for any or for an SDK, path or git dependency.
        hosted:
          type: boolean
          description: From a package repository, rather than an SDK, a path or git.
        local:
          type: boolean
          description: A package on this server, so it can be linked to.
    Version:
      type: object
      required: [version, published, uploader, retracted, prerelease, downloads, archiveSha256]
      properties:
        version:
          type: string
        published:
          $ref: '#/components/schemas/DateTime'
        uploader:
          type: [string, 'null']
        retracted:
          type: boolean
        prerelease:
          type: boolean
        downloads:
          type: integer
        archiveSha256:
          type: [string, 'null']
          description: >-
            The SHA-256 of the archive of this version, 64 hex characters, or
            null when it is not known, as for a version published before the
            server recorded it.
        createdAt:
          $ref: '#/components/schemas/DateTime'
          deprecated: true
          description: The same as `published`. Still sent, but not required; read `published`.
        isRetracted:
          type: boolean
          deprecated: true
          description: The same as `retracted`. Still sent, but not required; read `retracted`.
    Package:
      type: object
      description: >-
        A package at one version, with every version listed. It comes wrapped
        as `{"data": ...}`, a legacy of the former web UI that stays. Field
        names keep their former spelling where they had one (`isDiscontinued`,
        not `discontinued`); the deprecated twins `createdAt`, `isRetracted`,
        `authors` and `tags` are still sent.
      examples:
        - name: alpha_client
          version: 1.4.0
          latest: 1.4.0
          description: A client for the Alpha service.
          published: '2026-11-02T09:14:00.000Z'
          uploader: dev@example.com
          uploaders: [dev@example.com, lead@example.com]
          versions:
            - version: 1.4.0
              published: '2026-11-02T09:14:00.000Z'
              uploader: dev@example.com
              retracted: false
              prerelease: false
              downloads: 210
              archiveSha256: 3b1f0c9e0d4a7b2c5e6f8a9b0c1d2e3f4a5b6c7d8e9f0a1b2c3d4e5f6a7b8c9d
              createdAt: '2026-11-02T09:14:00.000Z'
              isRetracted: false
          readmeHtml: <h1>alpha_client</h1>
          changelogHtml: null
          readme: '# alpha_client'
          changelog: null
          dependencies:
            - name: http
              constraint: ^1.2.0
              hosted: true
              local: false
          devDependencies: []
          environment:
            sdk: ^3.5.0
            flutter: null
          platforms: []
          retracted: false
          retractedAt: null
          isDiscontinued: false
          replacedBy: null
          discontinuedAt: null
          archiveSha256: 3b1f0c9e0d4a7b2c5e6f8a9b0c1d2e3f4a5b6c7d8e9f0a1b2c3d4e5f6a7b8c9d
          downloads:
            version: 210
            package: 1287
          private: true
          isFlutter: false
          homepage: https://alpha.example.com
          repository: null
          issueTracker: null
          documentation: null
          license: null
      required:
        - name
        - version
        - latest
        - description
        - published
        - uploader
        - uploaders
        - versions
        - readmeHtml
        - changelogHtml
        - dependencies
        - devDependencies
        - environment
        - platforms
        - retracted
        - retractedAt
        - isDiscontinued
        - replacedBy
        - discontinuedAt
        - archiveSha256
        - downloads
        - private
        - isFlutter
        - homepage
        - repository
        - issueTracker
        - documentation
        - license
      properties:
        name:
          type: string
        version:
          type: string
          description: The version shown.
        latest:
          type: string
          description: >-
            The highest stable version that is not retracted, else the highest
            version that is not retracted, else the highest.
        description:
          type: string
        published:
          $ref: '#/components/schemas/DateTime'
        uploader:
          type: [string, 'null']
          description: Who published this version.
        uploaders:
          type: array
          items:
            type: string
        versions:
          type: array
          description: Every version, highest first.
          items:
            $ref: '#/components/schemas/Version'
        readmeHtml:
          type: [string, 'null']
          description: >-
            The README rendered as GitHub flavoured markdown and sanitized
            through an allowlist, relative links leading into the repository.
            Only the first 512 KiB are rendered. Null without a README.
        changelogHtml:
          type: [string, 'null']
          description: The CHANGELOG, as `readmeHtml`.
        readme:
          type: [string, 'null']
          description: The README as markdown, unsanitized. Never insert it as HTML.
        changelog:
          type: [string, 'null']
          description: The CHANGELOG as markdown, unsanitized.
        dependencies:
          type: array
          items:
            $ref: '#/components/schemas/Dependency'
        devDependencies:
          type: array
          items:
            $ref: '#/components/schemas/Dependency'
        environment:
          type: object
          required: [sdk, flutter]
          properties:
            sdk:
              type: [string, 'null']
            flutter:
              type: [string, 'null']
        platforms:
          type: array
          description: From `platforms`, or `flutter.plugin.platforms` for a plugin.
          items:
            type: string
        retracted:
          type: boolean
        retractedAt:
          oneOf:
            - $ref: '#/components/schemas/DateTime'
            - type: 'null'
        isRetracted:
          type: boolean
          deprecated: true
          description: The same as `retracted`.
        isDiscontinued:
          type: boolean
        replacedBy:
          type: [string, 'null']
        discontinuedAt:
          oneOf:
            - $ref: '#/components/schemas/DateTime'
            - type: 'null'
        archiveSha256:
          type: [string, 'null']
          description: The SHA-256 of the archive, 64 hex characters.
        downloads:
          type: object
          required: [version, package]
          properties:
            version:
              type: integer
            package:
              type: integer
        private:
          type: boolean
        isFlutter:
          type: boolean
        homepage:
          type: [string, 'null']
          format: uri
        repository:
          type: [string, 'null']
          format: uri
        issueTracker:
          type: [string, 'null']
          format: uri
        documentation:
          type: [string, 'null']
          format: uri
        license:
          type: [string, 'null']
          description: A `license` field of the pubspec, if it has one.
        createdAt:
          $ref: '#/components/schemas/DateTime'
