        authors:
          type: array
          deprecated: true
          items:
            type: [string, 'null']
        tags:
          type: array
          deprecated: true
          items:
            type: string
    PackageResponse:
      type: object
      required: [data]
      properties:
        data:
          $ref: '#/components/schemas/Package'
    Stats:
