              downloads: 210
            - version: 1.3.2
              downloads: 0
      properties:
        name:
          type: string
        total:
          type: integer
          description: Every download counted.
        recent:
          type: integer
          description: The downloads of `days`.
        days:
          type: array
          description: The last 30 days, oldest first, today included, by local day of the server, zeros filled in.
          minItems: 30
          maxItems: 30
          items:
            type: object
            required: [day, count]
            properties:
              day:
                type: string
                format: date
              count:
                type: integer
        versions:
          type: array
          description: Every version, most downloaded first.
          items:
