                type: string
              downloads:
                type: integer
    User:
      type: object
      required: [id, email, displayName, role, disabled, hasPassword, createdAt, updatedAt, lastLoginAt]
      examples:
        - id: 6730a1b2c3d4e5f6a7b8c9d0
          email: dev@example.com
          displayName: Dev Example
          role: publisher
          disabled: false
          hasPassword: true
          createdAt: '2026-10-01T08:00:00.000Z'
          updatedAt: '2026-10-01T08:00:00.000Z'
          lastLoginAt: '2026-11-09T07:45:12.000Z'
      properties:
        id:
          type: string
        email:
          type: string
        displayName:
          type: string
          description: Never null; the part of the email before `@` unless one was given.
        role:
          $ref: '#/components/schemas/Role'
        disabled:
          type: boolean
        hasPassword:
          type: boolean
          description: False for a placeholder that cannot log in.
        createdAt:
          $ref: '#/components/schemas/DateTime'
        updatedAt:
          $ref: '#/components/schemas/DateTime'
        lastLoginAt:
          oneOf:
            - $ref: '#/components/schemas/DateTime'
            - type: 'null'
    UserPage:
      allOf:
        - $ref: '#/components/schemas/PageInfo'
        - type: object
          required: [items]
          properties:
            items:
              type: array
              items:
                $ref: '#/components/schemas/User'
    Me:
      type: object
      required: [user, scopes]
      properties:
        user:
          description: The account, or for a static token from the configuration only its email and role, with `id` null.
          oneOf:
            - $ref: '#/components/schemas/User'
            - type: object
              required: [id, email, role]
              properties:
                id:
                  type: 'null'
                email:
                  type: string
                role:
                  $ref: '#/components/schemas/Role'
        scopes:
          type: array
          items:
            $ref: '#/components/schemas/Scope'
        csrfToken:
          type: string
          description: Only for a session.
    Anonymous:
      type: object
      description: The answer of `GET /webapi/me` when nobody is logged in.
      required: [user]
      additionalProperties: false
      properties:
        user:
          type: 'null'
      examples:
        - user: null
    LoginResult:
      type: object
      required: [user, csrfToken]
      properties:
        user:
          $ref: '#/components/schemas/User'
        csrfToken:
          type: string
    Token:
      type: object
      required: [id, userId, name, prefix, scopes, expiresAt, lastUsedAt, createdAt, revokedAt]
      examples:
        - id: 6730c0a1b2c3d4e5f6a7b8c9
          userId: 6730a1b2c3d4e5f6a7b8c9d0
          name: CI
          prefix: up_3f9a
          scopes: [read, publish]
          expiresAt: '2027-02-08T10:00:00.000Z'
          lastUsedAt: null
          createdAt: '2026-11-10T10:00:00.000Z'
          revokedAt: null
      properties:
        id:
          type: string
        userId:
          type: string
        name:
          type: string
        prefix:
          type: string
          description: The first characters of the secret.
        scopes:
          type: array
          items:
            $ref: '#/components/schemas/Scope'
        expiresAt:
          oneOf:
            - $ref: '#/components/schemas/DateTime'
            - type: 'null'
        lastUsedAt:
          oneOf:
            - $ref: '#/components/schemas/DateTime'
            - type: 'null'
        createdAt:
          $ref: '#/components/schemas/DateTime'
        revokedAt:
          oneOf:
            - $ref: '#/components/schemas/DateTime'
            - type: 'null'
    TokenCreated:
      type: object
      required: [token, secret]
      properties:
        token:
          $ref: '#/components/schemas/Token'
        secret:
          type: string
          description: Shown once. Use it with `dart pub token add <url>`.
    TokenPage:
      allOf:
        - $ref: '#/components/schemas/PageInfo'
        - type: object
          required: [items]
          properties:
            items:
              type: array
              items:
                $ref: '#/components/schemas/Token'
    AuditEvent:
      type: object
      required: [at, action, actor, actorKind, token, package, version, target, ip, details]
      examples:
        - at: '2026-11-02T09:14:00.000Z'
          action: package.published
          actor: dev@example.com
          actorKind: token
          token: up_3f9a
          package: alpha_client
          version: 1.4.0
          target: null
          ip: 10.0.0.12
          details: {}
      properties:
        at:
          $ref: '#/components/schemas/DateTime'
        action:
          type: string
          examples: [package.published]
        actor:
          type: [string, 'null']
          description: The email of who acted.
        actorKind:
          type: [string, 'null']
          description: The kind of credential, such as `session`, `token` or `static`.
        token:
          type: [string, 'null']
          description: The prefix of the token used.
        package:
          type: [string, 'null']
        version:
          type: [string, 'null']
        target:
          type: [string, 'null']
          description: The user, token or webhook acted on.
        ip:
          type: [string, 'null']
        details:
          type: object
          additionalProperties: true
    AuditPage:
      allOf:
        - $ref: '#/components/schemas/PageInfo'
        - type: object
          required: [items]
          properties:
            items:
              type: array
              items:
                $ref: '#/components/schemas/AuditEvent'
    WebhookEvent:
      type: string
      enum:
        - package.published
        - version.retracted
        - version.unretracted
        - package.discontinued
        - package.continued
        - version.deleted
        - package.deleted
    WebhookInput:
      type: object
      required: [url, events]
      properties:
        url:
          type: string
          format: uri
          description: https, or http with `webhooks.allowHttp`.
        events:
          type: array
          minItems: 1
          items:
            $ref: '#/components/schemas/WebhookEvent'
        description:
          type: string
    Webhook:
      type: object
      required: [id, url, events, description, enabled, createdAt, updatedAt, createdBy]
      examples:
        - id: 6730b0e1a9d3e4b5c6d7e8a1
          url: https://ci.example.com/hooks/unpub
          events: [package.published, version.retracted]
          description: Rebuild the docs
          enabled: true
          createdAt: '2026-10-20T12:00:00.000Z'
          updatedAt: '2026-10-20T12:00:00.000Z'
          createdBy: admin@example.com
      properties:
        id:
          type: string
        url:
          type: string
          format: uri
        events:
          type: array
          items:
            $ref: '#/components/schemas/WebhookEvent'
        description:
          type: string
        enabled:
          type: boolean
        createdAt:
          $ref: '#/components/schemas/DateTime'
        updatedAt:
          $ref: '#/components/schemas/DateTime'
        createdBy:
          type: [string, 'null']
    WebhookCreated:
      type: object
      required: [webhook, secret]
      properties:
        webhook:
          $ref: '#/components/schemas/Webhook'
        secret:
          type: string
          description: The key of the `X-Unpub-Signature` HMAC, shown once.
    WebhookPage:
      allOf:
        - $ref: '#/components/schemas/PageInfo'
        - type: object
          required: [items, enabled]
          properties:
            items:
              type: array
              items:
                allOf:
                  - $ref: '#/components/schemas/Webhook'
                  - type: object
                    required: [deliveries]
                    properties:
                      deliveries:
                        $ref: '#/components/schemas/DeliveryCounts'
            enabled:
              type: boolean
              description: '`webhooks.enabled`: whether events are queued and delivered.'
    DeliveryCounts:
      type: object
      description: How many deliveries have each status, zero included.
      required: [pending, succeeded, failed]
      examples:
        - pending: 1
          succeeded: 41
          failed: 2
      properties:
        pending:
          type: integer
        succeeded:
          type: integer
        failed:
          type: integer
      additionalProperties:
        type: integer
    Delivery:
      type: object
      description: >-
        One event sent to one webhook, with its attempts so far. Each attempt
        POSTs `payload` as the body, with `Content-Type: application/json`,
        `X-Unpub-Event`, `X-Unpub-Delivery` (the `id`) and
        `X-Unpub-Signature: sha256=<hex>`, the HMAC-SHA256 with the secret
        of the webhook as key over exactly the bytes of `payload` (UTF-8).
        Verify the signature over the raw body before parsing it. `status`
        `succeeded` means an answer in 2xx.
      required: [id, webhookId, event, eventId, package, version, payload, status, attempt, nextAt, createdAt, lastAttemptAt, finishedAt, durationMs, response, error, redeliveryOf]
      examples:
        - id: 6730c1f2a9d3e4b5c6d7e8f9
          webhookId: 6730b0e1a9d3e4b5c6d7e8a1
          event: package.published
          eventId: 0f8e4c2a-1b3d-4e5f-9a7b-6c5d4e3f2a1b
          package: alpha_client
          version: 1.4.0
          payload: '{"id":"0f8e4c2a-1b3d-4e5f-9a7b-6c5d4e3f2a1b","event":"package.published","at":"2026-11-02T09:14:00.000Z","package":"alpha_client","version":"1.4.0","actor":"dev@example.com","data":{}}'
          status: succeeded
          attempt: 1
          nextAt: null
          createdAt: '2026-11-02T09:14:00.120Z'
          lastAttemptAt: '2026-11-02T09:14:00.480Z'
          finishedAt: '2026-11-02T09:14:00.480Z'
          durationMs: 312
          response:
            status: 200
            body: ok
          error: null
          redeliveryOf: null
      properties:
        id:
          type: string
        webhookId:
          type: string
        event:
          $ref: '#/components/schemas/WebhookEvent'
        eventId:
          type: string
          description: The `id` of the payload, shared by a redelivery.
        package:
          type: [string, 'null']
        version:
          type: [string, 'null']
        payload:
          type: string
          description: >-
            The JSON body sent, as the exact string that was signed: the same on
            every attempt and redelivery of this delivery.
        status:
          type: string
          enum: [pending, succeeded, failed]
        attempt:
          type: integer
          description: Attempts made so far.
        nextAt:
          description: When a pending delivery is attempted next.
          oneOf:
            - $ref: '#/components/schemas/DateTime'
            - type: 'null'
        createdAt:
          $ref: '#/components/schemas/DateTime'
        lastAttemptAt:
          oneOf:
            - $ref: '#/components/schemas/DateTime'
            - type: 'null'
        finishedAt:
          oneOf:
            - $ref: '#/components/schemas/DateTime'
            - type: 'null'
        durationMs:
          type: [integer, 'null']
          minimum: 0
          description: >-
            How long the last attempt took, from resolving the host to reading
            the answer or failing. Null before the first attempt, when the
            webhook was deleted or disabled at the last attempt, and for
            attempts recorded before the field was added.
        response:
          description: The status and the start, at most 1 KiB, of the last answer.
          oneOf:
            - type: object
              required: [status, body]
              properties:
                status:
                  type: [integer, 'null']
                body:
                  type: [string, 'null']
            - type: 'null'
        error:
          type: [string, 'null']
        redeliveryOf:
          type: [string, 'null']
    DeliveryPage:
      allOf:
        - $ref: '#/components/schemas/PageInfo'
        - type: object
          required: [items]
          properties:
            items:
              type: array
              items:
                $ref: '#/components/schemas/Delivery'
    Settings:
      type: object
      required: [configured, sections]
      properties:
        configured:
          type: boolean
          description: False when the server was embedded without a configuration.
        sections:
          type: array
          items:
            type: object
            required: [name, settings]
            properties:
              name:
                type: string
                examples: [server]
              settings:
                type: array
                items:
                  type: object
                  required: [key, value, env]
                  properties:
                    key:
                      type: string
                      examples: [server.publicUrl]
                    value:
                      type: string
                      description: As shown on the settings page, secrets as `<redacted>`.
                    env:
                      type: string
                      description: The environment variable that sets the key.
                      examples: [UNPUB_SERVER_PUBLIC_URL]
    Readiness:
      type: object
      required: [status, checks]
      properties:
        status:
          type: string
          enum: [ok, unavailable]
        checks:
          type: object
          additionalProperties:
            type: object
            required: [status]
            properties:
              status:
                type: string
                enum: [ok, error]
              error:
                type: string
    Overview:
      type: object
      required:
        - packages
        - versions
        - users
        - webhooks
        - storageBytes
        - storageMeasuredAt
        - publishesLast24h
        - failedDeliveriesLast24h
        - recentPublishes
        - readiness
      properties:
        packages:
          type: [integer, 'null']
          description: Null when the store cannot count cheaply.
        versions:
          type: [integer, 'null']
        users:
          type: [integer, 'null']
          description: Null without user accounts.
        webhooks:
          type: [integer, 'null']
          description: Null without webhooks.
        storageBytes:
          type: [integer, 'null']
          description: Measured in the background at most every 10 minutes, null until measured or when the store cannot.
        storageMeasuredAt:
          oneOf:
            - $ref: '#/components/schemas/DateTime'
            - type: 'null'
        publishesLast24h:
          type: integer
          description: From the audit log.
        failedDeliveriesLast24h:
          type: integer
        recentPublishes:
          type: array
          description: The last 10 publishes, from the audit log.
          items:
            $ref: '#/components/schemas/AuditEvent'
        readiness:
          $ref: '#/components/schemas/Readiness'
    EmailInput:
      type: object
      required: [email]
      properties:
        email:
          type: string
          format: email
''';
